function esc(s) {
  return s.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

const tierTags = {
  major: { interests: ["building-products", "entrepreneurship", "technology"], skills: ["problem-solving", "organization", "critical-thinking"], workStyles: ["hands-on", "independent", "collaborative"] },
  specialized: { interests: ["building-products", "technology"], skills: ["problem-solving", "organization", "critical-thinking"], workStyles: ["hands-on", "independent", "technical"] },
  emerging: { interests: ["building-products", "technology", "environment"], skills: ["problem-solving", "creativity", "organization"], workStyles: ["hands-on", "collaborative", "independent"] },
  interdisciplinary: { interests: ["building-products", "healthcare", "science"], skills: ["problem-solving", "communication", "organization"], workStyles: ["hands-on", "collaborative", "people-focused"] },
  hidden: { interests: ["building-products", "entrepreneurship"], skills: ["organization", "problem-solving", "critical-thinking"], workStyles: ["hands-on", "independent", "technical"] },
};

let out = `import { GrowthOutlook } from "../../../src/generated/prisma/client";

import { c } from "../career-builder";

/** Trades & Skilled Work category — batch 14 of the 1,000+ career catalog. */
export const TRADES_SKILLED_WORK_CAREERS = [
`;

for (const row of careers) {
  const [slug, title, tagline, summary, min, max, opts = {}] = row;
  const tags = tierTags[opts.tier ?? "specialized"];
  const lines = [`  c({`];
  lines.push(`    slug: "${slug}",`);
  lines.push(`    title: "${esc(title)}",`);
  lines.push(`    tagline: "${esc(tagline)}",`);
  lines.push(`    summary: "${esc(summary)}",`);
  lines.push(`    salaryMin: ${min},`);
  lines.push(`    salaryMax: ${max},`);
  if (opts.anchor) lines.push(`    anchor: true,`);
  if (opts.featured) lines.push(`    featured: true,`);
  if (opts.tier) lines.push(`    tier: "${opts.tier}",`);
  if (opts.growth) lines.push(`    growthOutlook: GrowthOutlook.${opts.growth},`);
  if (opts.companies) lines.push(`    exampleCompanies: [${opts.companies.map((x) => `"${x}"`).join(", ")}],`);
  if (opts.aliases) lines.push(`    aliases: [${opts.aliases.map((x) => `"${esc(x)}"`).join(", ")}],`);
  if (opts.related) lines.push(`    related: [${opts.related.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    interests: [${tags.interests.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    skills: [${tags.skills.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    workStyles: [${tags.workStyles.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    commonTasks: "${esc(opts.tasks ?? "")}",`);
  lines.push(`    downsides: "${esc(opts.downsides ?? "")}",`);
  lines.push(`  }),`);
  out += lines.join("\n") + "\n";
}

out += `];\n`;

const outPath = path.join(__dirname, "../data/categories/trades-skilled-work.ts");
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, out);
console.log(`Generated ${careers.length} trades careers → ${outPath}`);
